mapper.select:
/* Attd11Mapper.selectAttdSummaryRows */ WITH RECURSIVE /* 1. 부서 트리 — 시작 노드부터 하위까지 (nodeCd 미지정 시 사업장 전체) */ node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
AND N.PARENT_NODE_CD IS NULL
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
),
/* 2. 대상 사용자 (USE_YN='Y', 미퇴사) */ target_user AS ( SELECT U.CMPNY_CD , U.SITE_CD , U.USER_CD , U.USER_ID , U.USER_NM , U.NODE_CD , U.AUTH_CD , NT.NODE_NM FROM TB_USER U INNER JOIN node_tree NT ON U.CMPNY_CD = NT.CMPNY_CD AND U.SITE_CD = NT.SITE_CD AND U.NODE_CD = NT.NODE_CD WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
)
/* 3. 메인 — 출퇴근 실적(차수 행) + 차수별 유효 스케줄 결합 */ SELECT U.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , U.NODE_NM AS deptNm , U.AUTH_CD AS authCd , FNC_CMM_INFO_SRCH(U.CMPNY_CD, 'BAIM_VAL', U.AUTH_CD, 'COM005') AS authNm
, A.WORK_YMD AS workYmd , A.WORK_SEQ AS workSeq
/* 차수에 맞춰 정규화한 스케줄 계획시각/휴게 (1구간/2구간) */ , CASE WHEN A.WORK_SEQ = 2 THEN SCH.SEC_SCH_STR_TIME ELSE SCH.FST_SCH_STR_TIME END AS planStart , CASE WHEN A.WORK_SEQ = 2 THEN SCH.SEC_SCH_END_TIME ELSE SCH.FST_SCH_END_TIME END AS planEnd , CASE WHEN A.WORK_SEQ = 2 THEN SCH.SEC_SCH_BRK_MIN ELSE SCH.FST_SCH_BRK_MIN END AS planBreakMin
/* 실제(원본) 출퇴근 일시 — 표준화 아님 */ , A.CHECK_IN_DATE AS actInDate , A.CHECK_IN_TIME AS actInTime , A.CHECK_OUT_DATE AS actOutDate , A.CHECK_OUT_TIME AS actOutTime
FROM target_user U INNER JOIN TB_USER_ATTD_MGMT A ON A.CMPNY_CD = U.CMPNY_CD AND A.SITE_CD = U.SITE_CD AND A.USER_CD = U.USER_CD AND A.WORK_SEQ IN (1, 2) AND A.DEL_YN = 'N' AND A.WORK_YMD LIKE CONCAT(REPLACE(#{workYm}, '-', ''), '%')
LEFT JOIN TB_USER_WORK_PLAN WP ON WP.CMPNY_CD = A.CMPNY_CD AND WP.SITE_CD = A.SITE_CD AND WP.USER_CD = A.USER_CD AND WP.WORK_YMD = A.WORK_YMD
/* 근무계획코드가 스케줄코드인 경우 — 근무일(A.WORK_YMD) 기준 유효 스케줄(effective-dating). TB_SCH_MGMT(현재본) + TB_SCH_MGMT_HIST(전 버전) UNION 후 APPLY_DATE <= WORK_YMD 인 가장 최근 버전의 시간값을 결합한다. (attd07 selectMonthlyAttdList 의 SCH 서브쿼리 그대로 재사용) */ LEFT JOIN ( SELECT E.CMPNY_CD , E.SITE_CD , E.SCH_CD , E.APPLY_DATE , E.FST_SCH_STR_TIME , E.FST_SCH_END_TIME , E.FST_SCH_BRK_MIN , E.SEC_SCH_STR_TIME , E.SEC_SCH_END_TIME , E.SEC_SCH_BRK_MIN FROM ( SELECT M.CMPNY_CD , M.SITE_CD , M.SCH_CD , M.APPLY_DATE , M.FST_SCH_STR_TIME , M.FST_SCH_END_TIME , M.FST_SCH_BRK_MIN , M.SEC_SCH_STR_TIME , M.SEC_SCH_END_TIME , M.SEC_SCH_BRK_MIN , 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M WHERE M.USE_YN = 'Y'
UNION ALL
SELECT H.CMPNY_CD , H.SITE_CD , H.SCH_CD , H.APPLY_DATE , H.FST_SCH_STR_TIME , H.FST_SCH_END_TIME , H.FST_SCH_BRK_MIN , H.SEC_SCH_STR_TIME , H.SEC_SCH_END_TIME , H.SEC_SCH_BRK_MIN , H.HIST_IDX FROM TB_SCH_MGMT_HIST H WHERE H.USE_YN = 'Y' ) E WHERE E.HIST_IDX = ( SELECT MAX(E2.HIST_IDX) FROM ( SELECT M2.CMPNY_CD, M2.SITE_CD, M2.SCH_CD, M2.APPLY_DATE, 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M2 WHERE M2.USE_YN = 'Y' UNION ALL SELECT H2.CMPNY_CD, H2.SITE_CD, H2.SCH_CD, H2.APPLY_DATE, H2.HIST_IDX FROM TB_SCH_MGMT_HIST H2 WHERE H2.USE_YN = 'Y' ) E2 WHERE E2.CMPNY_CD = E.CMPNY_CD AND E2.SITE_CD = E.SITE_CD AND E2.SCH_CD = E.SCH_CD AND E2.APPLY_DATE = E.APPLY_DATE ) ) SCH ON SCH.CMPNY_CD = WP.CMPNY_CD AND SCH.SITE_CD = WP.SITE_CD AND SCH.SCH_CD = WP.WORK_PLAN_CD AND SCH.APPLY_DATE = ( SELECT MAX(SE.APPLY_DATE) FROM ( SELECT M3.CMPNY_CD, M3.SITE_CD, M3.SCH_CD, M3.APPLY_DATE FROM TB_SCH_MGMT M3 WHERE M3.USE_YN = 'Y' UNION ALL SELECT H3.CMPNY_CD, H3.SITE_CD, H3.SCH_CD, H3.APPLY_DATE FROM TB_SCH_MGMT_HIST H3 WHERE H3.USE_YN = 'Y' ) SE WHERE SE.CMPNY_CD = WP.CMPNY_CD AND SE.SITE_CD = WP.SITE_CD AND SE.SCH_CD = WP.WORK_PLAN_CD AND SE.APPLY_DATE <= WP.WORK_YMD )
ORDER BY U.USER_CD, A.WORK_YMD, A.WORK_SEQ

/* Attd11Mapper.selectOvertimeSummary */ WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
AND N.PARENT_NODE_CD IS NULL
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
),
target_user AS ( SELECT U.CMPNY_CD , U.SITE_CD , U.USER_CD , U.USER_ID , U.USER_NM , U.AUTH_CD , NT.NODE_NM FROM TB_USER U INNER JOIN node_tree NT ON U.CMPNY_CD = NT.CMPNY_CD AND U.SITE_CD = NT.SITE_CD AND U.NODE_CD = NT.NODE_CD WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
)
/* OT-only(정규 출근기록 없는 휴일 초과근무 등) 사용자도 1행으로 노출하기 위해 사용자 기본정보(userId/userNm/deptNm/authCd/authNm)를 함께 내려준다. */ SELECT O.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , U.NODE_NM AS deptNm , U.AUTH_CD AS authCd , FNC_CMM_INFO_SRCH(U.CMPNY_CD, 'BAIM_VAL', U.AUTH_CD, 'COM005') AS authNm , IFNULL(SUM(O.WORK_MINUTES), 0) AS otMinutes FROM TB_USER_OVERTIME_MGMT O INNER JOIN target_user U ON O.CMPNY_CD = U.CMPNY_CD AND O.SITE_CD = U.SITE_CD AND O.USER_CD = U.USER_CD WHERE O.CMPNY_CD = #{gvCmpnyCd} AND O.SITE_CD = #{siteCd} AND O.WORK_YMD LIKE CONCAT(REPLACE(#{workYm}, '-', ''), '%') AND O.DEL_YN = 'N' AND O.OT_STATUS = 'COMPLETED' GROUP BY O.USER_CD, U.CMPNY_CD, U.USER_ID, U.USER_NM, U.NODE_NM, U.AUTH_CD
